-- Supplier arrangements, actual quarantine withdrawal and independent supplier receipt.
CREATE TABLE supplier_return_plans(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES purchase_quality_cases(id),receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),supplier_id TEXT NOT NULL REFERENCES suppliers(id),store_id TEXT NOT NULL REFERENCES stores(id),serial INTEGER NOT NULL CHECK(serial>0),return_number TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),source_note TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,return_number));
CREATE TABLE supplier_return_versions(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES supplier_return_plans(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),quality_sequence INTEGER NOT NULL CHECK(quality_sequence>=0),receipt_sequence INTEGER NOT NULL CHECK(receipt_sequence>=0),quality_version_id TEXT NOT NULL REFERENCES purchase_quality_versions(id),quality_event_id TEXT NOT NULL REFERENCES purchase_quality_events(id),receipt_version_id TEXT NOT NULL REFERENCES purchase_receipt_versions(id),return_basis TEXT NOT NULL,destination_note TEXT NOT NULL,contact_note TEXT,source_reference TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(plan_id,version));
CREATE TABLE supplier_return_events(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES supplier_return_plans(id),version_id TEXT NOT NULL REFERENCES supplier_return_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),quality_sequence INTEGER NOT NULL CHECK(quality_sequence>=0),receipt_sequence INTEGER NOT NULL CHECK(receipt_sequence>=0),action TEXT NOT NULL CHECK(action IN('create','revise','submit','approve','reject','reopen','cancel','stop_remaining')),status TEXT NOT NULL CHECK(status IN('draft','submitted','approved','rejected','cancelled','closed_partial')),decision_basis TEXT NOT NULL,note TEXT NOT NULL,reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(plan_id,revision),UNIQUE(store_id,sequence));
CREATE TABLE supplier_return_handoffs(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES supplier_return_plans(id),version_id TEXT NOT NULL REFERENCES supplier_return_versions(id),approval_event_id TEXT NOT NULL REFERENCES supplier_return_events(id),case_id TEXT NOT NULL REFERENCES purchase_quality_cases(id),receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),store_id TEXT NOT NULL REFERENCES stores(id),product_id TEXT NOT NULL REFERENCES retail_products(id),product_version INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),case_revision INTEGER NOT NULL CHECK(case_revision>0),product_revision INTEGER NOT NULL CHECK(product_revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),stock_sequence INTEGER NOT NULL CHECK(stock_sequence>=0),outbound_revision INTEGER NOT NULL CHECK(outbound_revision>=0),handed_at TEXT NOT NULL,collector_label TEXT NOT NULL,destination_note TEXT NOT NULL,external_reference TEXT,source_identity TEXT,source_note TEXT NOT NULL,reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(case_id,case_revision),UNIQUE(product_id,product_revision),UNIQUE(store_id,sequence),FOREIGN KEY(product_id,product_version) REFERENCES retail_product_versions(product_id,version));
CREATE UNIQUE INDEX supplier_return_handoff_identity ON supplier_return_handoffs(plan_id,source_identity) WHERE source_identity IS NOT NULL;
CREATE TABLE supplier_return_receipts(id TEXT PRIMARY KEY,handoff_id TEXT NOT NULL REFERENCES supplier_return_handoffs(id),store_id TEXT NOT NULL REFERENCES stores(id),quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),sequence INTEGER NOT NULL CHECK(sequence>0),received_at TEXT NOT NULL,receiver_label TEXT NOT NULL,external_reference TEXT,source_identity TEXT,source_note TEXT NOT NULL,reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,sequence));
CREATE UNIQUE INDEX supplier_return_receipt_identity ON supplier_return_receipts(handoff_id,source_identity) WHERE source_identity IS NOT NULL;
CREATE TABLE purchase_quality_version_return_context(version_id TEXT PRIMARY KEY REFERENCES purchase_quality_versions(id),case_id TEXT NOT NULL REFERENCES purchase_quality_cases(id),case_return_revision INTEGER NOT NULL CHECK(case_return_revision>=0),remaining_quantity INTEGER NOT NULL CHECK(remaining_quantity>=0));
CREATE TABLE purchase_quality_event_return_context(event_id TEXT PRIMARY KEY REFERENCES purchase_quality_events(id),return_sequence INTEGER NOT NULL CHECK(return_sequence>=0),case_id TEXT NOT NULL REFERENCES purchase_quality_cases(id),case_return_revision INTEGER NOT NULL CHECK(case_return_revision>=0),product_return_revision INTEGER NOT NULL CHECK(product_return_revision>=0),remaining_quantity INTEGER NOT NULL CHECK(remaining_quantity>=0));
CREATE TABLE inventory_dispatch_return_context(outbound_id TEXT PRIMARY KEY REFERENCES inventory_outbounds(id),product_return_revision INTEGER NOT NULL CHECK(product_return_revision>=0));
CREATE TABLE inventory_event_return_context(stock_event_id TEXT PRIMARY KEY REFERENCES inventory_events(id),product_return_revision INTEGER NOT NULL CHECK(product_return_revision>=0));
INSERT INTO purchase_quality_version_return_context SELECT v.id,v.case_id,0,c.quantity FROM purchase_quality_versions v JOIN purchase_quality_cases c ON c.id=v.case_id;
INSERT INTO purchase_quality_event_return_context SELECT e.id,0,e.case_id,0,0,c.quantity FROM purchase_quality_events e JOIN purchase_quality_cases c ON c.id=e.case_id;
INSERT INTO inventory_dispatch_return_context SELECT id,0 FROM inventory_outbounds;
INSERT INTO inventory_event_return_context SELECT id,0 FROM inventory_events;
CREATE VIEW supplier_return_current AS SELECT * FROM supplier_return_events e WHERE revision=(SELECT max(revision) FROM supplier_return_events WHERE plan_id=e.plan_id);
CREATE VIEW supplier_return_journal AS SELECT store_id,sequence,id,created_at FROM supplier_return_events UNION ALL SELECT store_id,sequence,id,created_at FROM supplier_return_handoffs UNION ALL SELECT store_id,sequence,id,created_at FROM supplier_return_receipts;
CREATE VIEW supplier_return_plan_balance AS SELECT p.id,p.case_id,p.receipt_id,p.store_id,p.quantity,coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE plan_id=p.id),0) handed_quantity,coalesce((SELECT sum(r.quantity) FROM supplier_return_receipts r JOIN supplier_return_handoffs h ON h.id=r.handoff_id WHERE h.plan_id=p.id),0) received_quantity,coalesce(c.status,'draft') status,CASE WHEN coalesce(c.status,'draft') IN('draft','submitted','approved') THEN p.quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE plan_id=p.id),0) ELSE 0 END pending_quantity FROM supplier_return_plans p LEFT JOIN supplier_return_current c ON c.plan_id=p.id;
CREATE VIEW supplier_return_case_balance AS SELECT c.id case_id,c.receipt_id,c.quantity,coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE case_id=c.id),0) returned_quantity,c.quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE case_id=c.id),0) remaining_quantity,coalesce((SELECT max(case_revision) FROM supplier_return_handoffs WHERE case_id=c.id),0) case_return_revision,coalesce((SELECT sum(pending_quantity) FROM supplier_return_plan_balance WHERE case_id=c.id),0) pending_quantity FROM purchase_quality_cases c;
DROP VIEW purchase_quality_holds;
CREATE VIEW purchase_quality_holds AS SELECT r.product_id,c.receipt_id,c.id case_id,b.remaining_quantity quantity FROM purchase_quality_cases c JOIN purchase_receipts r ON r.id=c.receipt_id JOIN purchase_quality_current e ON e.case_id=c.id JOIN supplier_return_case_balance b ON b.case_id=c.id WHERE e.status<>'released';
DROP VIEW inventory_balances;
CREATE VIEW inventory_balances AS SELECT e.id,e.product_id,e.product_version,e.store_id,e.sequence,e.action,e.quantity,e.available,e.reserved,e.quarantined-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE product_id=e.product_id),0) quarantined,e.order_event_id,e.order_position,e.reason,max(e.created_at,coalesce((SELECT max(created_at) FROM supplier_return_handoffs WHERE product_id=e.product_id),e.created_at)) created_at,e.created_by,e.available-coalesce((SELECT sum(quantity) FROM inventory_outbounds WHERE product_id=e.product_id AND source_mode='available'),0) effective_available,e.reserved-coalesce((SELECT sum(quantity) FROM inventory_outbounds WHERE product_id=e.product_id AND source_mode='reserved'),0) effective_reserved,coalesce((SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=e.product_id),0) outbound_revision,coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=e.product_id),0) return_revision FROM inventory_events e WHERE e.sequence=(SELECT max(sequence) FROM inventory_events WHERE product_id=e.product_id);
CREATE TRIGGER supplier_return_plan_source BEFORE INSERT ON supplier_return_plans BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_cases c JOIN purchase_quality_current q ON q.case_id=c.id JOIN purchase_receipts r ON r.id=c.receipt_id JOIN supplier_return_case_balance b ON b.case_id=c.id WHERE c.id=NEW.case_id AND c.receipt_id=NEW.receipt_id AND r.supplier_id=NEW.supplier_id AND c.store_id=NEW.store_id AND q.status<>'released' AND NEW.quantity<=b.remaining_quantity-b.pending_quantity AND c.created_at<=NEW.created_at) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM supplier_return_plans WHERE store_id=NEW.store_id),1) THEN RAISE(ABORT,'supplier return original protected case/capacity') END;
END;
CREATE TRIGGER supplier_return_version_source BEFORE INSERT ON supplier_return_versions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM supplier_return_plans p JOIN purchase_quality_current q ON q.case_id=p.case_id JOIN purchase_receipt_versions r ON r.receipt_id=p.receipt_id WHERE p.id=NEW.plan_id AND p.store_id=NEW.store_id AND q.id=NEW.quality_event_id AND q.version_id=NEW.quality_version_id AND q.status<>'released' AND r.id=NEW.receipt_version_id AND r.version=(SELECT max(version) FROM purchase_receipt_versions WHERE receipt_id=p.receipt_id) AND q.created_at<=NEW.created_at AND r.created_at<=NEW.created_at) OR NEW.quality_sequence<>coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=NEW.store_id),0) OR NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR NEW.version<>coalesce((SELECT max(version)+1 FROM supplier_return_versions WHERE plan_id=NEW.plan_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM supplier_return_journal WHERE store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM supplier_return_current WHERE plan_id=NEW.plan_id AND status<>'draft') OR EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE plan_id=NEW.plan_id) THEN RAISE(ABORT,'supplier return actual arrangement version') END;
END;
CREATE TRIGGER supplier_return_event_source BEFORE INSERT ON supplier_return_events BEGIN
 SELECT CASE WHEN NEW.quality_sequence<>coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=NEW.store_id),0) OR NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM supplier_return_events WHERE plan_id=NEW.plan_id),1) OR NOT EXISTS(SELECT 1 FROM supplier_return_versions v WHERE v.id=NEW.version_id AND v.plan_id=NEW.plan_id AND v.store_id=NEW.store_id AND v.version=(SELECT max(version) FROM supplier_return_versions WHERE plan_id=NEW.plan_id) AND v.created_at<=NEW.created_at) THEN RAISE(ABORT,'supplier return current version/revision') END;
 SELECT CASE WHEN NOT(NEW.action='create' AND NEW.revision=1 AND NEW.status='draft' AND EXISTS(SELECT 1 FROM supplier_return_plans p JOIN supplier_return_versions v ON v.plan_id=p.id WHERE p.id=NEW.plan_id AND v.id=NEW.version_id AND v.version=1 AND v.base_sequence+1=NEW.sequence AND p.created_at=NEW.created_at AND p.created_by=NEW.created_by AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by) OR NEW.action='revise' AND NEW.status='draft' AND EXISTS(SELECT 1 FROM supplier_return_current c JOIN supplier_return_versions old ON old.id=c.version_id JOIN supplier_return_versions v ON v.id=NEW.version_id WHERE c.plan_id=NEW.plan_id AND c.status='draft' AND v.version=old.version+1 AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by) OR EXISTS(SELECT 1 FROM supplier_return_current c JOIN supplier_return_plan_balance b ON b.id=c.plan_id WHERE c.plan_id=NEW.plan_id AND c.version_id=NEW.version_id AND(NEW.action='submit' AND c.status='draft' AND NEW.status='submitted' OR NEW.action='approve' AND c.status='submitted' AND NEW.status='approved' OR NEW.action='reject' AND c.status='submitted' AND NEW.status='rejected' OR NEW.action='reopen' AND c.status IN('approved','rejected') AND b.handed_quantity=0 AND NEW.status='draft' OR NEW.action='cancel' AND c.status IN('draft','submitted','approved','rejected') AND b.handed_quantity=0 AND NEW.status='cancelled' OR NEW.action='stop_remaining' AND c.status='approved' AND b.handed_quantity>0 AND b.handed_quantity<b.quantity AND NEW.status='closed_partial'))) THEN RAISE(ABORT,'supplier return explicit commercial transition') END;
 SELECT CASE WHEN NEW.action IN('submit','approve') AND NOT EXISTS(SELECT 1 FROM supplier_return_plans p JOIN supplier_return_versions v ON v.id=NEW.version_id JOIN purchase_quality_current q ON q.case_id=p.case_id JOIN purchase_receipt_versions r ON r.id=v.receipt_version_id JOIN supplier_return_case_balance b ON b.case_id=p.case_id WHERE p.id=NEW.plan_id AND q.id=v.quality_event_id AND q.version_id=v.quality_version_id AND q.status<>'released' AND r.version=(SELECT max(version) FROM purchase_receipt_versions WHERE receipt_id=p.receipt_id) AND p.quantity<=b.remaining_quantity-coalesce((SELECT sum(pending_quantity) FROM supplier_return_plan_balance WHERE case_id=p.case_id AND id<>p.id),0)) THEN RAISE(ABORT,'supplier return current source/claim capacity') END;
END;
CREATE TRIGGER supplier_return_handoff_source BEFORE INSERT ON supplier_return_handoffs BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM supplier_return_plans p JOIN supplier_return_current e ON e.plan_id=p.id JOIN supplier_return_plan_balance b ON b.id=p.id JOIN purchase_quality_current q ON q.case_id=p.case_id JOIN supplier_return_case_balance cb ON cb.case_id=p.case_id JOIN purchase_receipts r ON r.id=p.receipt_id WHERE p.id=NEW.plan_id AND e.id=NEW.approval_event_id AND e.action='approve' AND e.status='approved' AND e.version_id=NEW.version_id AND p.case_id=NEW.case_id AND p.receipt_id=NEW.receipt_id AND p.store_id=NEW.store_id AND r.product_id=NEW.product_id AND r.product_version=NEW.product_version AND q.status<>'released' AND NEW.quantity<=p.quantity-b.handed_quantity AND NEW.quantity<=cb.remaining_quantity AND e.created_at<=NEW.handed_at AND NEW.stock_sequence=(SELECT max(sequence) FROM inventory_events WHERE product_id=r.product_id) AND NEW.outbound_revision=coalesce((SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=r.product_id),0) AND NEW.quantity<=(SELECT quarantined FROM inventory_balances WHERE product_id=r.product_id)) OR NEW.case_revision<>coalesce((SELECT max(case_revision)+1 FROM supplier_return_handoffs WHERE case_id=NEW.case_id),1) OR NEW.product_revision<>coalesce((SELECT max(product_revision)+1 FROM supplier_return_handoffs WHERE product_id=NEW.product_id),1) OR EXISTS(SELECT 1 FROM inventory_events WHERE product_id=NEW.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_outbounds WHERE product_id=NEW.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE product_id=NEW.product_id AND created_at>NEW.created_at) THEN RAISE(ABORT,'supplier return actual stock/case/approval source') END;
 SELECT CASE WHEN length(NEW.handed_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.handed_at) IS NOT NEW.handed_at OR NEW.handed_at>NEW.created_at THEN RAISE(ABORT,'supplier return actual handover time') END;
END;
CREATE TRIGGER supplier_return_receipt_source BEFORE INSERT ON supplier_return_receipts BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM supplier_return_handoffs h WHERE h.id=NEW.handoff_id AND h.store_id=NEW.store_id AND NEW.quantity+coalesce((SELECT sum(quantity) FROM supplier_return_receipts WHERE handoff_id=h.id),0)<=h.quantity AND NEW.received_at>=h.handed_at) OR length(NEW.received_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.received_at) IS NOT NEW.received_at OR NEW.received_at>NEW.created_at THEN RAISE(ABORT,'supplier return actual supplier receipt source/time/capacity') END;
END;
CREATE TRIGGER supplier_return_quality_claim BEFORE INSERT ON purchase_quality_cases WHEN NOT EXISTS(SELECT 1 FROM purchase_receipts r WHERE r.id=NEW.receipt_id AND NEW.quantity+coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)) BEGIN SELECT RAISE(ABORT,'supplier return original receipt remaining quantity'); END;
CREATE TRIGGER supplier_return_quality_version_ready BEFORE INSERT ON purchase_quality_versions WHEN NOT EXISTS(SELECT 1 FROM supplier_return_case_balance WHERE case_id=NEW.case_id AND remaining_quantity>0) BEGIN SELECT RAISE(ABORT,'supplier return case no actual stock remains'); END;
CREATE TRIGGER supplier_return_quality_positive BEFORE INSERT ON purchase_quality_events WHEN NEW.action IN('quality_pass','release') AND NOT EXISTS(SELECT 1 FROM supplier_return_case_balance b JOIN purchase_quality_version_return_context v ON v.case_id=b.case_id WHERE b.case_id=NEW.case_id AND v.version_id=NEW.version_id AND v.case_return_revision=b.case_return_revision AND b.remaining_quantity>0 AND(NEW.action<>'release' OR b.pending_quantity=0)) BEGIN SELECT RAISE(ABORT,'supplier return changed actual case/unfinished arrangement'); END;
CREATE TRIGGER supplier_return_stock_time BEFORE INSERT ON inventory_events WHEN EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE product_id=NEW.product_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'supplier return stock chronology'); END;
DROP TRIGGER purchase_quality_event_source;
CREATE TRIGGER purchase_quality_event_source BEFORE INSERT ON purchase_quality_events BEGIN
 SELECT CASE WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM purchase_quality_journal WHERE store_id=NEW.store_id),1) OR NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM purchase_quality_events WHERE case_id=NEW.case_id),1) OR EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM purchase_quality_versions v WHERE v.id=NEW.version_id AND v.case_id=NEW.case_id AND v.store_id=NEW.store_id AND v.version=(SELECT max(version) FROM purchase_quality_versions WHERE case_id=NEW.case_id) AND v.created_at<=NEW.created_at) THEN RAISE(ABORT,'purchase quality journal/version') END;
 SELECT CASE WHEN NOT(NEW.action='create' AND NEW.revision=1 AND NEW.status='pending' AND EXISTS(SELECT 1 FROM purchase_quality_cases c JOIN purchase_quality_versions v ON v.case_id=c.id WHERE c.id=NEW.case_id AND v.id=NEW.version_id AND v.version=1 AND c.created_at=NEW.created_at AND c.created_by=NEW.created_by AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.base_sequence+1=NEW.sequence) OR NEW.action='revise' AND NEW.status='pending' AND EXISTS(SELECT 1 FROM purchase_quality_current e JOIN purchase_quality_versions old ON old.id=e.version_id JOIN purchase_quality_versions v ON v.id=NEW.version_id WHERE e.case_id=NEW.case_id AND e.status<>'released' AND v.version=old.version+1 AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by) OR EXISTS(SELECT 1 FROM purchase_quality_current e WHERE e.case_id=NEW.case_id AND e.version_id=NEW.version_id AND(NEW.action='quality_pass' AND e.status='pending' AND NEW.status='passed' OR NEW.action='quality_fail' AND e.status='pending' AND NEW.status='failed' OR NEW.action='release' AND e.status='passed' AND NEW.status='released'))) THEN RAISE(ABORT,'purchase quality explicit transition') END;
 SELECT CASE WHEN NEW.action IN('quality_pass','release') AND NOT EXISTS(SELECT 1 FROM purchase_quality_versions v JOIN purchase_quality_cases c ON c.id=v.case_id JOIN purchase_receipt_versions r ON r.id=v.receipt_version_id WHERE v.id=NEW.version_id AND r.version=(SELECT max(version) FROM purchase_receipt_versions WHERE receipt_id=c.receipt_id) AND(r.expiry_date IS NULL OR r.expiry_date>=substr(CASE WHEN NEW.action='quality_pass' THEN NEW.checked_at ELSE NEW.created_at END,1,10))) THEN RAISE(ABORT,'purchase quality current receipt source/expiry') END;
 SELECT CASE WHEN NEW.action='quality_pass' AND NOT EXISTS(SELECT 1 FROM purchase_quality_versions v JOIN purchase_receipt_versions r ON r.id=v.receipt_version_id WHERE v.id=NEW.version_id AND(NEW.require_lot=0 OR r.lot_status='recorded') AND(NEW.require_expiry=0 OR r.expiry_status='provided') AND(NEW.require_location=0 OR r.location_status='recorded')) THEN RAISE(ABORT,'purchase quality required actual provenance') END;
 SELECT CASE WHEN NEW.action IN('quality_pass','quality_fail') AND(NEW.checked_at IS NULL OR length(NEW.checked_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.checked_at) IS NOT NEW.checked_at OR NEW.checked_at>NEW.created_at OR NEW.checked_at<(SELECT observed_at FROM purchase_quality_versions WHERE id=NEW.version_id) OR NEW.requirement_source IS NULL OR length(trim(NEW.requirement_source)) NOT BETWEEN 1 AND 2000 OR length(NEW.requirement_source)>2000 OR NEW.require_lot IS NULL OR NEW.require_lot NOT IN(0,1) OR NEW.require_expiry IS NULL OR NEW.require_expiry NOT IN(0,1) OR NEW.require_location IS NULL OR NEW.require_location NOT IN(0,1) OR NEW.checks_json IS NULL OR json_valid(NEW.checks_json)=0 OR json_type(NEW.checks_json)<>'array' OR json_array_length(NEW.checks_json) NOT BETWEEN 1 AND 30 OR EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_type(j.value)<>'object' OR(SELECT count(*) FROM json_each(j.value))<>2 OR json_type(j.value,'$.label') IS NOT 'text' OR length(trim(json_extract(j.value,'$.label'))) NOT BETWEEN 1 AND 300 OR length(json_extract(j.value,'$.label'))>300 OR json_type(j.value,'$.result') IS NOT 'text' OR json_extract(j.value,'$.result') NOT IN('pass','fail')) OR NEW.action='quality_pass' AND EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_extract(j.value,'$.result')<>'pass') OR NEW.action='quality_fail' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.checks_json) j WHERE json_extract(j.value,'$.result')='fail')) THEN RAISE(ABORT,'purchase quality actual checks') END;
 SELECT CASE WHEN NEW.action='release' AND(NEW.quality_event_id IS NOT(SELECT id FROM purchase_quality_current WHERE case_id=NEW.case_id AND action='quality_pass') OR NEW.stock_sequence IS NULL OR NEW.outbound_revision IS NULL OR NOT EXISTS(SELECT 1 FROM purchase_quality_cases c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.case_id AND NEW.stock_sequence=(SELECT max(sequence) FROM inventory_events WHERE product_id=r.product_id) AND NEW.outbound_revision=coalesce((SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=r.product_id),0) AND (SELECT remaining_quantity FROM supplier_return_case_balance WHERE case_id=c.id)<=(SELECT quarantined FROM inventory_balances WHERE product_id=r.product_id))) THEN RAISE(ABORT,'purchase quality release stock source') END;
 SELECT CASE WHEN NEW.action NOT IN('quality_pass','quality_fail') AND(NEW.checked_at IS NOT NULL OR NEW.requirement_source IS NOT NULL OR NEW.require_lot IS NOT NULL OR NEW.require_expiry IS NOT NULL OR NEW.require_location IS NOT NULL OR NEW.checks_json IS NOT NULL) OR NEW.action<>'release' AND(NEW.quality_event_id IS NOT NULL OR NEW.stock_sequence IS NOT NULL OR NEW.outbound_revision IS NOT NULL) THEN RAISE(ABORT,'purchase quality unrelated facts') END;
END;
DROP TRIGGER purchase_quality_stock_ref_source;
CREATE TRIGGER purchase_quality_stock_ref_source BEFORE INSERT ON purchase_quality_stock_refs BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_events e JOIN purchase_quality_cases c ON c.id=e.case_id JOIN purchase_receipts r ON r.id=c.receipt_id JOIN inventory_events s ON s.id=NEW.stock_event_id WHERE e.id=NEW.event_id AND(e.action='release' AND s.action='unquarantine' AND s.sequence=e.stock_sequence+1 OR e.action='create' AND c.source_bucket='available' AND s.action='isolate' AND s.sequence=c.stock_sequence+1) AND s.product_id=r.product_id AND s.product_version=r.product_version AND s.store_id=c.store_id AND s.quantity=(SELECT remaining_quantity FROM purchase_quality_event_return_context WHERE event_id=e.id) AND s.order_event_id IS NULL AND s.created_at=e.created_at AND s.created_by=e.created_by AND s.reason=e.reason) THEN RAISE(ABORT,'purchase quality original stock reference') END;
END;
CREATE TRIGGER supplier_return_quality_version_capture AFTER INSERT ON purchase_quality_versions BEGIN INSERT INTO purchase_quality_version_return_context SELECT NEW.id,NEW.case_id,case_return_revision,remaining_quantity FROM supplier_return_case_balance WHERE case_id=NEW.case_id; END;
CREATE TRIGGER supplier_return_quality_event_capture AFTER INSERT ON purchase_quality_events BEGIN INSERT INTO purchase_quality_event_return_context SELECT NEW.id,coalesce((SELECT max(sequence) FROM supplier_return_journal WHERE store_id=NEW.store_id),0),NEW.case_id,b.case_return_revision,coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=r.product_id),0),b.remaining_quantity FROM supplier_return_case_balance b JOIN purchase_receipts r ON r.id=b.receipt_id WHERE b.case_id=NEW.case_id; END;
CREATE TRIGGER supplier_return_inventory_event_capture AFTER INSERT ON inventory_events BEGIN INSERT INTO inventory_event_return_context VALUES(NEW.id,coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=NEW.product_id),0)); END;
CREATE TRIGGER supplier_return_dispatch_capture AFTER INSERT ON inventory_outbounds BEGIN INSERT INTO inventory_dispatch_return_context VALUES(NEW.id,coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=NEW.product_id),0)); END;
CREATE TRIGGER purchase_quality_version_return_context_source BEFORE INSERT ON purchase_quality_version_return_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_versions v JOIN supplier_return_case_balance b ON b.case_id=v.case_id WHERE v.id=NEW.version_id AND v.case_id=NEW.case_id AND b.case_return_revision=NEW.case_return_revision AND b.remaining_quantity=NEW.remaining_quantity) BEGIN SELECT RAISE(ABORT,'supplier return original context'); END;
CREATE TRIGGER purchase_quality_event_return_context_source BEFORE INSERT ON purchase_quality_event_return_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_events e JOIN supplier_return_case_balance b ON b.case_id=e.case_id JOIN purchase_receipts r ON r.id=b.receipt_id WHERE e.id=NEW.event_id AND NEW.return_sequence=coalesce((SELECT max(sequence) FROM supplier_return_journal WHERE store_id=e.store_id),0) AND e.case_id=NEW.case_id AND b.case_return_revision=NEW.case_return_revision AND b.remaining_quantity=NEW.remaining_quantity AND NEW.product_return_revision=coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=r.product_id),0)) BEGIN SELECT RAISE(ABORT,'supplier return original context'); END;
CREATE TRIGGER inventory_event_return_context_source BEFORE INSERT ON inventory_event_return_context WHEN NOT EXISTS(SELECT 1 FROM inventory_events e WHERE e.id=NEW.stock_event_id AND NEW.product_return_revision=coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=e.product_id),0)) BEGIN SELECT RAISE(ABORT,'supplier return original context'); END;
CREATE TRIGGER inventory_dispatch_return_context_source BEFORE INSERT ON inventory_dispatch_return_context WHEN NOT EXISTS(SELECT 1 FROM inventory_outbounds e WHERE e.id=NEW.outbound_id AND NEW.product_return_revision=coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=e.product_id),0)) BEGIN SELECT RAISE(ABORT,'supplier return original context'); END;
CREATE TRIGGER supplier_return_plans_actor BEFORE INSERT ON supplier_return_plans WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(q.must_change_password,0)=0 AND (u.role='manager')) BEGIN SELECT RAISE(ABORT,'supplier return actor/time'); END;
CREATE TRIGGER supplier_return_plans_text BEFORE INSERT ON supplier_return_plans WHEN (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000) BEGIN SELECT RAISE(ABORT,'supplier return actual source text'); END;
CREATE TRIGGER supplier_return_versions_actor BEFORE INSERT ON supplier_return_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(q.must_change_password,0)=0 AND (u.role='manager')) BEGIN SELECT RAISE(ABORT,'supplier return actor/time'); END;
CREATE TRIGGER supplier_return_versions_text BEFORE INSERT ON supplier_return_versions WHEN (length(trim(NEW.return_basis)) NOT BETWEEN 1 AND 2000 OR length(NEW.return_basis)>2000) OR (length(trim(NEW.destination_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.destination_note)>2000) OR (length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) OR (NEW.contact_note IS NOT NULL AND(length(trim(NEW.contact_note)) NOT BETWEEN 1 AND 1000 OR length(NEW.contact_note)>1000)) BEGIN SELECT RAISE(ABORT,'supplier return actual source text'); END;
CREATE TRIGGER supplier_return_events_actor BEFORE INSERT ON supplier_return_events WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(q.must_change_password,0)=0 AND (u.role='manager')) BEGIN SELECT RAISE(ABORT,'supplier return actor/time'); END;
CREATE TRIGGER supplier_return_events_text BEFORE INSERT ON supplier_return_events WHEN (length(trim(NEW.decision_basis)) NOT BETWEEN 1 AND 2000 OR length(NEW.decision_basis)>2000) OR (length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) OR (length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000) BEGIN SELECT RAISE(ABORT,'supplier return actual source text'); END;
CREATE TRIGGER supplier_return_events_journal BEFORE INSERT ON supplier_return_events WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM supplier_return_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM supplier_return_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'supplier return actual journal'); END;
CREATE TRIGGER supplier_return_handoffs_actor BEFORE INSERT ON supplier_return_handoffs WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(q.must_change_password,0)=0 AND (u.role='manager')) BEGIN SELECT RAISE(ABORT,'supplier return actor/time'); END;
CREATE TRIGGER supplier_return_handoffs_text BEFORE INSERT ON supplier_return_handoffs WHEN (length(trim(NEW.collector_label)) NOT BETWEEN 1 AND 120 OR length(NEW.collector_label)>120) OR (length(trim(NEW.destination_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.destination_note)>2000) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) OR (length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000) OR (NEW.external_reference IS NOT NULL AND(length(trim(NEW.external_reference)) NOT BETWEEN 1 AND 120 OR length(NEW.external_reference)>120)) OR (NEW.source_identity IS NOT NULL AND(length(trim(NEW.source_identity)) NOT BETWEEN 1 AND 120 OR length(NEW.source_identity)>120)) BEGIN SELECT RAISE(ABORT,'supplier return actual source text'); END;
CREATE TRIGGER supplier_return_handoffs_journal BEFORE INSERT ON supplier_return_handoffs WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM supplier_return_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM supplier_return_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'supplier return actual journal'); END;
CREATE TRIGGER supplier_return_receipts_actor BEFORE INSERT ON supplier_return_receipts WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(q.must_change_password,0)=0 AND (u.role IN('manager','reception'))) BEGIN SELECT RAISE(ABORT,'supplier return actor/time'); END;
CREATE TRIGGER supplier_return_receipts_text BEFORE INSERT ON supplier_return_receipts WHEN (length(trim(NEW.receiver_label)) NOT BETWEEN 1 AND 120 OR length(NEW.receiver_label)>120) OR (length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) OR (length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000) OR (NEW.external_reference IS NOT NULL AND(length(trim(NEW.external_reference)) NOT BETWEEN 1 AND 120 OR length(NEW.external_reference)>120)) OR (NEW.source_identity IS NOT NULL AND(length(trim(NEW.source_identity)) NOT BETWEEN 1 AND 120 OR length(NEW.source_identity)>120)) BEGIN SELECT RAISE(ABORT,'supplier return actual source text'); END;
CREATE TRIGGER supplier_return_receipts_journal BEFORE INSERT ON supplier_return_receipts WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM supplier_return_journal WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM supplier_return_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'supplier return actual journal'); END;
