CREATE TRIGGER supplier_return_handoffs_no_delete BEFORE DELETE ON supplier_return_handoffs BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER supplier_return_receipts_no_update BEFORE UPDATE ON supplier_return_receipts BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER supplier_return_receipts_no_delete BEFORE DELETE ON supplier_return_receipts BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER purchase_quality_version_return_context_no_update BEFORE UPDATE ON purchase_quality_version_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER purchase_quality_version_return_context_no_delete BEFORE DELETE ON purchase_quality_version_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER purchase_quality_event_return_context_no_update BEFORE UPDATE ON purchase_quality_event_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER purchase_quality_event_return_context_no_delete BEFORE DELETE ON purchase_quality_event_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER inventory_event_return_context_no_update BEFORE UPDATE ON inventory_event_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
CREATE TRIGGER inventory_event_return_context_no_delete BEFORE DELETE ON inventory_event_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;
