CREATE TRIGGER inventory_dispatch_return_context_no_delete BEFORE DELETE ON inventory_dispatch_return_context BEGIN SELECT RAISE(ABORT,'supplier return immutable'); END;

CREATE TRIGGER supplier_return_reopen_capacity BEFORE INSERT ON supplier_return_events WHEN NEW.action='reopen' AND NOT EXISTS(SELECT 1 FROM supplier_return_plans p JOIN supplier_return_case_balance b ON b.case_id=p.case_id JOIN purchase_quality_current q ON q.case_id=p.case_id WHERE p.id=NEW.plan_id AND q.status<>'released' AND p.quantity<=b.remaining_quantity-coalesce((SELECT sum(pending_quantity) FROM supplier_return_plan_balance WHERE case_id=p.case_id AND id<>p.id),0)) BEGIN SELECT RAISE(ABORT,'supplier return remaining reopen capacity'); END;
CREATE TRIGGER supplier_return_number BEFORE INSERT ON supplier_return_plans WHEN NEW.return_number IS NOT 'RTV-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) BEGIN SELECT RAISE(ABORT,'supplier return original number'); END;
